const art="<div class=\"art\" aria-hidden=\"true\"><svg viewBox=\"0 0 238 170\"><defs><radialGradient id=\"world\"><stop stop-color=\"#e6e9cc\"/><stop offset=\"1\" stop-color=\"#cdd6b5\"/></radialGradient><linearGradient id=\"fur\" x2=\".8\" y2=\"1\"><stop stop-color=\"#fffdf2\"/><stop offset=\"1\" stop-color=\"#e4e4d6\"/></linearGradient></defs><ellipse cx=\"120\" cy=\"149\" rx=\"83\" ry=\"11\" fill=\"#a5b392\" opacity=\".15\"/><ellipse cx=\"120\" cy=\"132\" rx=\"80\" ry=\"24\" fill=\"url(#world)\"/><path d=\"M70 136q22-24 73 3\" fill=\"none\" stroke=\"#f7f4dd\" stroke-width=\"8\"/><g transform=\"translate(92 54)\"><ellipse cx=\"24\" cy=\"65\" rx=\"29\" ry=\"34\" fill=\"url(#fur)\"/><circle cx=\"2\" cy=\"8\" r=\"12\" fill=\"url(#fur)\"/><circle cx=\"46\" cy=\"8\" r=\"12\" fill=\"url(#fur)\"/><circle cx=\"2\" cy=\"8\" r=\"6\" fill=\"#dedfce\"/><circle cx=\"46\" cy=\"8\" r=\"6\" fill=\"#dedfce\"/><ellipse cx=\"24\" cy=\"29\" rx=\"33\" ry=\"30\" fill=\"url(#fur)\"/><ellipse cx=\"-2\" cy=\"69\" rx=\"9\" ry=\"18\" transform=\"rotate(16 -2 69)\" fill=\"url(#fur)\"/><ellipse cx=\"49\" cy=\"68\" rx=\"9\" ry=\"18\" transform=\"rotate(-20 49 68)\" fill=\"url(#fur)\"/><ellipse cx=\"12\" cy=\"92\" rx=\"12\" ry=\"8\" fill=\"#eeeee1\"/><ellipse cx=\"39\" cy=\"92\" rx=\"12\" ry=\"8\" fill=\"#eeeee1\"/><circle cx=\"14\" cy=\"28\" r=\"2.5\" fill=\"#384536\"/><circle cx=\"36\" cy=\"28\" r=\"2.5\" fill=\"#384536\"/><ellipse cx=\"25\" cy=\"38\" rx=\"9\" ry=\"7\" fill=\"#fdf9ed\"/><ellipse cx=\"25\" cy=\"35\" rx=\"4\" ry=\"3\" fill=\"#384536\"/><path d=\"M25 38v3\" stroke=\"#384536\"/><path d=\"M2 53q21 9 44 0\" fill=\"none\" stroke=\"#d3b76c\" stroke-width=\"7\" stroke-linecap=\"round\"/><path d=\"M34 57l-2 15\" stroke=\"#d3b76c\" stroke-width=\"7\"/></g><g stroke=\"#849d73\" fill=\"none\" stroke-linecap=\"round\"><path d=\"M54 130v-14m0 9-5-5m5 8 6-6M175 138v-20m0 12 7-7\"/></g><circle cx=\"175\" cy=\"116\" r=\"4\" fill=\"#f9f4db\"/><path d=\"M178 54l4-7m-2 13 8-1\" stroke=\"#c5cfb4\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></div>";
const choices="<div class=\"choices\"><button class=\"bear-option\" type=\"button\" aria-pressed=\"true\" data-bear=\"0\"><svg viewBox=\"0 0 50 50\"><g fill=\"#fffdf1\" stroke=\"#d4d8c8\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><circle cx=\"38\" cy=\"12\" r=\"8\"/><ellipse cx=\"25\" cy=\"27\" rx=\"21\" ry=\"20\"/></g><circle cx=\"18\" cy=\"25\" r=\"2\" fill=\"#354d3a\"/><circle cx=\"32\" cy=\"25\" r=\"2\" fill=\"#354d3a\"/><ellipse cx=\"25\" cy=\"32\" rx=\"3\" ry=\"2\" fill=\"#354d3a\"/></svg>白熊<span class=\"check\">✓</span></button><button class=\"bear-option\" type=\"button\" aria-pressed=\"false\" data-bear=\"1\"><svg viewBox=\"0 0 50 50\"><g fill=\"#b99772\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><circle cx=\"38\" cy=\"12\" r=\"8\"/><ellipse cx=\"25\" cy=\"27\" rx=\"21\" ry=\"20\"/></g><circle cx=\"18\" cy=\"25\" r=\"2\" fill=\"#483c2e\"/><circle cx=\"32\" cy=\"25\" r=\"2\" fill=\"#483c2e\"/><ellipse cx=\"25\" cy=\"32\" rx=\"3\" ry=\"2\" fill=\"#483c2e\"/></svg>棕熊<span class=\"check\"></span></button></div>";
export function authenticate(gate,session,api){return new Promise(resolve=>{
 let register=false,avatar=0,busy=false;gate.classList.add('auth-gate');
 function render(){avatar=0;gate.innerHTML=`<main class="auth-page"><div class="brand"><span class="mark"></span>阿球 <span class="brand-en">Echoo</span></div>${art}<header><h1>${register?'留一颗星球给你。':'回来就好。'}</h1><p>${register?'从这里，开始自己的小日子。':'你的星球，在这里等你。'}</p></header><nav class="tabs" aria-label="账号操作"><button type="button" data-mode="login" class="tab ${register?'':'active'}" aria-pressed="${!register}">登录</button><button type="button" data-mode="register" class="tab ${register?'active':''}" aria-pressed="${register}">注册</button></nav><form id="cloud-auth"><label class="field">账号名<input name="username" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" required pattern="[a-zA-Z0-9_-]{3,24}" maxlength="24" placeholder="${register?'3–24 位字母、数字或下划线':'你的账号名'}"></label><label class="field pass">密码<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required minlength="10" maxlength="128" placeholder="${register?'设置密码，至少 10 位':'输入密码'}"><button class="eye" type="button" aria-label="显示密码">◉</button></label>${register?'<div class="character"><span>选一个你</span>'+choices+'</div>':''}<p id="cloud-error" role="alert"></p><button type="submit" class="main-button">${register?'住进星球':'回到星球'}</button></form>${register?'':'<button type="button" class="foot-action">忘记密码？</button>'}<div class="auth-bottom">有人在惦记你</div></main>`;
 const form=gate.querySelector('form'),err=gate.querySelector('#cloud-error');
 gate.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(busy)return;register=b.dataset.mode==='register';render()});
 gate.querySelectorAll('[data-bear]').forEach(b=>b.onclick=()=>{avatar=Number(b.dataset.bear);gate.querySelectorAll('[data-bear]').forEach(x=>{x.setAttribute('aria-pressed',x===b);x.querySelector('.check').textContent=x===b?'✓':''})});
 gate.querySelector('.eye').onclick=e=>{const p=form.elements.password;p.type=p.type==='password'?'text':'password';e.currentTarget.setAttribute('aria-label',p.type==='password'?'显示密码':'隐藏密码')};
 const help=gate.querySelector('.foot-action');if(help)help.onclick=()=>err.textContent='请联系服务器主人重置密码，账号和存档会保留。';
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const button=form.querySelector('[type=submit]');button.disabled=true;err.textContent='';try{const data={username:form.elements.username.value.trim(),password:form.elements.password.value};if(register)data.actor=avatar;resolve(await api(register?'/api/register':'/api/login',data))}catch(e){err.textContent=e.message||'暂时连接不上，请再试一次';button.disabled=false}finally{busy=false}};
 }
 render();
})}
